BEGIN;
CREATE TABLE external_sources (source_id text PRIMARY KEY, source_name text NOT NULL, provider text NOT NULL, source_type text NOT NULL, source_class text NOT NULL, access_method text NOT NULL, canonical_domain text NOT NULL, owner_organization text NOT NULL, market_families jsonb NOT NULL, licensing_note text NOT NULL, credentials_required boolean NOT NULL, credential_boundary text, expected_cadence text NOT NULL, expected_latency_ms integer, monthly_cost numeric NOT NULL, source_state text NOT NULL, production_influence numeric NOT NULL CHECK(production_influence=0), verification_method text NOT NULL, retention_days integer NOT NULL, last_success timestamptz, last_failure timestamptz, health text NOT NULL);
CREATE TABLE source_credentials_metadata (source_id text PRIMARY KEY REFERENCES external_sources(source_id), credential_type text NOT NULL, encrypted_secret_reference text, installed_at timestamptz, last_validated_at timestamptz, scope_description text, CHECK(encrypted_secret_reference IS NULL OR encrypted_secret_reference NOT LIKE '%BEGIN%'));
CREATE TABLE source_health (source_id text REFERENCES external_sources(source_id), observed_at timestamptz NOT NULL, availability text NOT NULL, source_to_ingest_latency_ms numeric, reconnect_count integer NOT NULL, dropped_events integer NOT NULL, invalid_events integer NOT NULL, parse_failures integer NOT NULL, duplicate_rate numeric NOT NULL, heartbeat_healthy boolean NOT NULL, provider_outage boolean NOT NULL, processing_lag_ms numeric NOT NULL, queue_depth integer NOT NULL, PRIMARY KEY(source_id,observed_at));
CREATE TABLE external_events (event_id text PRIMARY KEY, provider_event_id text, source_id text NOT NULL REFERENCES external_sources(source_id), source_type text NOT NULL, author_stable_id text, author_display_identity text, canonical_url text, original_event_id text, raw_content_hash text NOT NULL, normalized_content_hash text NOT NULL, source_event_time timestamptz, source_publish_time timestamptz, provider_receive_time timestamptz, bot_ingest_time timestamptz NOT NULL, receive_monotonic_ns bigint NOT NULL, raw_payload_reference text NOT NULL, deletion_state text NOT NULL, correction_of_event_id text REFERENCES external_events(event_id), language text, linked_entities jsonb NOT NULL, verification_state text NOT NULL, originality_state text NOT NULL, manipulation_flags jsonb NOT NULL, parser_version text NOT NULL, UNIQUE(source_id,provider_event_id));
CREATE TABLE external_event_duplicates (event_id text PRIMARY KEY REFERENCES external_events(event_id), duplicate_of_event_id text NOT NULL REFERENCES external_events(event_id), reason text NOT NULL, similarity numeric, detected_at timestamptz NOT NULL);
CREATE TABLE signal_observations (signal_id text PRIMARY KEY, detected_at timestamptz NOT NULL, category text NOT NULL, entities jsonb NOT NULL, numeric_facts jsonb NOT NULL, verification_state text NOT NULL, independent_source_chains integer NOT NULL, originality_state text NOT NULL, duplicate_count integer NOT NULL, source_class text NOT NULL, fresh boolean NOT NULL, manipulation_flags jsonb NOT NULL, status text NOT NULL, action text NOT NULL, relevance text NOT NULL, lead_lag jsonb NOT NULL, production_influence numeric NOT NULL CHECK(production_influence=0));
CREATE TABLE signal_market_links (signal_id text REFERENCES signal_observations(signal_id), venue text NOT NULL, market_id text NOT NULL, match_class text NOT NULL, semantic_fields jsonb NOT NULL, PRIMARY KEY(signal_id,venue,market_id));
CREATE TABLE signal_corroboration_links (signal_id text REFERENCES signal_observations(signal_id), external_event_id text REFERENCES external_events(event_id), independent_chain_id text NOT NULL, relationship text NOT NULL, PRIMARY KEY(signal_id,external_event_id));
CREATE TABLE cross_venue_market_matches (kalshi_ticker text NOT NULL, polymarket_market_id text NOT NULL, classification text NOT NULL, matched_fields jsonb NOT NULL, conflicts jsonb NOT NULL, created_at timestamptz NOT NULL, invalidated_at timestamptz, PRIMARY KEY(kalshi_ticker,polymarket_market_id,created_at));
CREATE TABLE cross_venue_price_observations (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, kalshi_ticker text NOT NULL, polymarket_market_id text NOT NULL, match_class text NOT NULL, kalshi_yes_bid numeric, kalshi_yes_ask numeric, polymarket_yes_bid numeric, polymarket_yes_ask numeric, kalshi_observed_at timestamptz NOT NULL, polymarket_observed_at timestamptz NOT NULL, freshness_difference_ms bigint NOT NULL, source_lag_ms bigint NOT NULL, observation_type text NOT NULL);
CREATE TABLE polymarket_events (event_id text PRIMARY KEY, title text NOT NULL, end_time timestamptz, resolved boolean NOT NULL, updated_at timestamptz, raw_payload jsonb NOT NULL);
CREATE TABLE polymarket_markets (market_id text PRIMARY KEY, event_id text REFERENCES polymarket_events(event_id), condition_id text NOT NULL, question text NOT NULL, description text, outcomes jsonb NOT NULL, resolved boolean NOT NULL, end_time timestamptz, orderbook_enabled boolean NOT NULL, tick_size numeric NOT NULL, minimum_size numeric NOT NULL, negative_risk boolean NOT NULL, multi_outcome boolean NOT NULL, updated_at timestamptz, raw_payload jsonb NOT NULL);
CREATE TABLE polymarket_assets (asset_id text PRIMARY KEY, market_id text NOT NULL REFERENCES polymarket_markets(market_id), outcome text NOT NULL, current_tick_size numeric NOT NULL, ladder_valid boolean NOT NULL);
CREATE TABLE polymarket_public_trades (trade_id text PRIMARY KEY, market_id text NOT NULL, asset_id text NOT NULL, price numeric NOT NULL, size numeric NOT NULL, side text, trade_at timestamptz NOT NULL, ingested_at timestamptz NOT NULL, wallet_id text, raw_hash text NOT NULL);
CREATE TABLE public_trader_profiles (wallet_id text PRIMARY KEY, provider_display_name text, leaderboard_rank integer, provider_realized_pnl numeric, observed_volume numeric NOT NULL, activity_count integer NOT NULL, market_families jsonb NOT NULL, observed_at timestamptz NOT NULL);
CREATE TABLE wallet_observations (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, wallet_id text NOT NULL, market_id text NOT NULL, absolute_size numeric NOT NULL, relative_to_volume numeric, relative_to_depth numeric, relative_to_typical numeric, concentration numeric, directional_accumulation numeric, vendor_label text, vendor text, observed_at timestamptz NOT NULL);
CREATE TABLE source_latency_metrics (source_id text REFERENCES external_sources(source_id), bucket_start timestamptz NOT NULL, publication_to_ingest_p50_ms numeric, publication_to_ingest_p99_ms numeric, event_to_ingest_p50_ms numeric, event_count integer NOT NULL, PRIMARY KEY(source_id,bucket_start));
CREATE TABLE market_reaction_snapshots (signal_id text REFERENCES signal_observations(signal_id), offset_seconds integer NOT NULL, venue text NOT NULL, market_id text NOT NULL, yes_bid numeric, yes_ask numeric, no_bid numeric, no_ask numeric, bid_size numeric, ask_size numeric, observed_at timestamptz NOT NULL, ingested_at timestamptz NOT NULL, fresh boolean NOT NULL, PRIMARY KEY(signal_id,offset_seconds,venue,market_id));
CREATE TABLE connector_runs (run_id uuid PRIMARY KEY, source_id text REFERENCES external_sources(source_id), started_at timestamptz NOT NULL, finished_at timestamptz, state text NOT NULL, requests bigint NOT NULL, events bigint NOT NULL, bytes bigint NOT NULL, processing_ms bigint NOT NULL, estimated_cost numeric NOT NULL, gap_markers integer NOT NULL, failure text);
CREATE TABLE raw_external_archive_manifests (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, source_id text REFERENCES external_sources(source_id), object_key text NOT NULL UNIQUE, first_received_at timestamptz NOT NULL, last_received_at timestamptz NOT NULL, event_count integer NOT NULL, compressed_bytes bigint NOT NULL, sha256 text NOT NULL, content_type text NOT NULL, parser_version text NOT NULL, retention_until timestamptz NOT NULL, deletion_policy text NOT NULL);
CREATE INDEX external_events_source_time_idx ON external_events(source_id,bot_ingest_time DESC); CREATE INDEX signals_time_status_idx ON signal_observations(detected_at DESC,status); CREATE INDEX polymarket_active_idx ON polymarket_markets(resolved,end_time); CREATE INDEX reaction_signal_idx ON market_reaction_snapshots(signal_id,offset_seconds);
COMMIT;
